(4644676, 669541, 6519, '<td valign="top">I think we''re a bit too used to seeing our moon to let it count as "paranormal".</td>', 'I think we''re a bit too used to seeing our moon to let it count as "paranormal".', '2008-04-16 21:20:47.000000', NULL, 1),
