(4644698, 669989, 83080, '<td valign="top">This is SO funny and it''s well done to boot!  Fantastic sharpness and detail in the cat and the overall composition leads my eyes around with pleasurable ease.</td>', 'This is SO funny and it''s well done to boot!  Fantastic sharpness and detail in the cat and the overall composition leads my eyes around with pleasurable ease.', '2008-04-16 21:27:41.000000', NULL, 1),
(4644701, 669454, 83080, '<td valign="top">EEeeewwwwww!  Now THAT''s macro!  The light is a little harsh, but who cares, this is just way closer than normal humans have a right to be to this thing.  Very effective.</td>', 'EEeeewwwwww!  Now THAT''s macro!  The light is a little harsh, but who cares, this is just way closer than normal humans have a right to be to this thing.  Very effective.', '2008-04-16 21:30:10.000000', NULL, 1),
