(4645778, 669927, 47470, '<td valign="top">I wish there were a bit more contrast and sharpness on the background.</td>', 'I wish there were a bit more contrast and sharpness on the background.', '2008-04-17 12:49:51.000000', NULL, 1),
(4645787, 669441, 58516, '<td valign="top">O-M-G Like...I can''t beleeeve you stood on gravestones...w-ooo-w. That is like...the WORST thing you could do...like...EVER. You are going STRAIGHT to hell young lady. And also, you are too fat to be standing on the graves! OMG LIKE what if they broke under your gigantic FATNESS? IMO you SUCK...and you''re UGLY! This picture would be better WITHOUT you. And also, the family members of these people from the 1800s must be UBER pissed at you. Srsly. Way to ruin my day.</td>', 'O-M-G Like...I can''t beleeeve you stood on gravestones...w-ooo-w. That is like...the WORST thing you could do...like...EVER. You are going STRAIGHT to hell young lady. And also, you are too fat to be standing on the graves! OMG LIKE what if they broke under your gigantic FATNESS? IMO you SUCK...and you''re UGLY! This picture would be better WITHOUT you. And also, the family members of these people from the 1800s must be UBER pissed at you. Srsly. Way to ruin my day.', '2008-04-17 12:54:06.000000', NULL, 1),
(4645877, 668757, 84124, '<td valign="top">First genuinely creepy apparition of the challenge, that open door and light really do the trick.  well done, 7.</td>', 'First genuinely creepy apparition of the challenge, that open door and light really do the trick.  well done, 7.', '2008-04-17 13:58:02.000000', NULL, 1),
